let inTopic = msg.topic || "";
let inPayload = msg.payload;
let outMsgLegacy = null;
let outMsgsApp = [];
let outMsgBroadlink = null;
let semanticEvidence = null;

function getNestedValue(obj, path) {
    return path.split(".").reduce(
        (acc, part) => (acc !== undefined && acc !== null) ? acc[part] : undefined,
        obj
    );
}

function transformValue(config, value, lastVal) {
    if (config.transform_func) {
        return config.transform_func(value, lastVal);
    }

    if (config.transform && config.transform[value] !== undefined) {
        return config.transform[value];
    }

    if (
        typeof value !== "boolean" &&
        value !== "" &&
        !isNaN(parseFloat(value))
    ) {
        return parseFloat(value);
    }

    return value;
}

// ROUTER-DEDUP.1: publish a Digital Twin state only when its value changes, or as a
// heartbeat at most every STATE_HEARTBEAT_MS. The retained value on the broker is
// unchanged; lastSensorValues (used by transform_func) is still updated every time.
const STATE_HEARTBEAT_MS = 60000;
const lastPublishedStates = context.get("lastPublishedStates") || {};

function emitState(config, value) {
    const lastVal = lastSensorValues[config.topic || config.int_stat];
    const outPayload = transformValue(config, value, lastVal);

    if (outPayload === undefined || outPayload === null) {
        // ROUTER-HEARTBEAT.1: an energy reading inside its per-entity deadband still proves
        // the source is alive. Republish the last published value at most every
        // STATE_HEARTBEAT_MS so the app can tell "steady" from "no data" (energy only).
        const hbTopic = config.topic || config.int_stat;
        const previousState = lastPublishedStates[hbTopic];
        if (previousState && hbTopic.indexOf("zara/interface/energy/") === 0 &&
            Date.now() - previousState.at >= STATE_HEARTBEAT_MS) {
            previousState.at = Date.now();
            context.set("lastPublishedStates", lastPublishedStates);
            outMsgsApp.push({
                topic: hbTopic,
                payload: JSON.parse(previousState.payload),
                qos: 1,
                retain: true
            });
        }
        return;
    }

    const topic = config.topic || config.int_stat;
    lastSensorValues[topic] = outPayload;

    const nowMs = Date.now();
    const serialized = JSON.stringify(outPayload);
    const previous = lastPublishedStates[topic];
    if (previous && previous.payload === serialized && nowMs - previous.at < STATE_HEARTBEAT_MS) {
        return;
    }
    lastPublishedStates[topic] = { payload: serialized, at: nowMs };
    context.set("lastPublishedStates", lastPublishedStates);

    outMsgsApp.push({
        topic: topic,
        payload: outPayload,
        qos: 1,
        retain: true
    });
}

const BROADLINK_INTERNAL_TOPICS = new Set([
    "zara/domotics/lights/shelflamp",
    "zara/domotics/lights/livinglamp",
    "zara/domotics/lights/tvlamp",
    "zara/domotics/lights/readinglight",
    "zara/domotics/lights/prolunga"
]);

// -----------------------------------------------------------------------------
// SCENE COMMAND BRIDGE
// -----------------------------------------------------------------------------
if (inTopic === "zara/interface/lights/scene/cmd") {
    return [null, null, null, msg];
}

// 1) UI / Digital Twin command -> Legacy command
if (inTopic.startsWith("zara/interface/")) {
    const route = mapCmdToLegacy[inTopic];

    if (route) {
        let outPayload = inPayload;

        if (route.transform && route.transform[inPayload] !== undefined) {
            outPayload = route.transform[inPayload];
        }

        // Semantic evidence only: the Router selected this route, not hardware confirmation.
        const entity = registry.find(e => e.int_cmd === inTopic);
        const normalized = String(inPayload).trim().toLowerCase();
        if (entity && /^(lights\.|pool\.(water|deck)\.)/.test(entity.id) &&
            ['true','false','1','0','on','off'].includes(normalized) && msg.retain !== true) {
            const time = Date.now();
            const sequence = (context.get('semantic_route_sequence') || 0) + 1;
            context.set('semantic_route_sequence', sequence);
            const evidence = {
                schema: 'domopi.semantic_command.v1', entity_id: entity.id,
                command_id: node.id + ':' + time + ':' + sequence,
                actor_policy:'dashboard_only_v2',actor: 'utente', origin: 'app_interface', attribution: 'interface_contract',
                publisher_authenticated: false, stage: 'routed',
                requested_state: ['true','1','on'].includes(normalized),
                observed_at_ms: time, input_topic: inTopic,
                routed_topic: route.topic, routed_broker: route.broker,
                execution_confirmed: false, physical_confirmation: false
            };
            semanticEvidence = [
                {topic:'zara/interface/semantic/v1/routed_commands/' + entity.id + '/stat',
                 payload:JSON.stringify(evidence),qos:1,retain:true},
                {topic:'zara/interface/semantic/v1/events',
                 payload:JSON.stringify({...evidence,schema:'domopi.semantic_event.v1',
                   event_id:evidence.command_id,kind:'user_command_routed'}),qos:1,retain:false}
            ];
        }

        const routedMsg = {
            topic: route.topic,
            payload: outPayload,
            broker: route.broker
        };

        // Le luci Broadlink verificate vengono inoltrate internamente
        // a function 17, evitando il publish MQTT intermedio.
        if (BROADLINK_INTERNAL_TOPICS.has(route.topic)) {
            // Internal provenance only; function 17 strips it before operational outputs.
            if (semanticEvidence) routedMsg._semantic_command = JSON.parse(semanticEvidence[0].payload);
            outMsgBroadlink = routedMsg;
        } else {
            outMsgLegacy = routedMsg;
        }
    }
}

// 2) Topic JSON composito -> singoli state del Digital Twin
else if (inTopic === COMPOSITE_TOPIC) {
    let compositePayload = inPayload;

    // MQTT-in normalmente può essere configurato per fornire un object,
    // ma accettiamo anche una stringa JSON per rendere il router robusto.
    if (typeof compositePayload === "string") {
        try {
            compositePayload = JSON.parse(compositePayload);
        } catch (err) {
            node.warn("Digital Twin Router: JSON non valido su " + COMPOSITE_TOPIC);
            compositePayload = null;
        }
    }

    if (
        compositePayload &&
        typeof compositePayload === "object" &&
        !Array.isArray(compositePayload)
    ) {
        compositeRegistry.forEach(config => {
            const value = getNestedValue(compositePayload, config.json_path);

            if (
                value !== undefined &&
                (value !== null || config.allow_null === true)
            ) {
                emitState(config, value);
            }
        });

        context.set("lastSensorValues", lastSensorValues);
    }
}

// 3) Topic legacy puntuale -> Digital Twin state
else {
    const routes = mapLegacyToStat[inTopic];

    if (routes && routes.length > 0) {
        routes.forEach(route => emitState(route, inPayload));
        context.set("lastSensorValues", lastSensorValues);
    }
}
return [
    outMsgLegacy,
    outMsgsApp.length > 0 ? outMsgsApp : null,
    outMsgBroadlink,
    null,
    semanticEvidence
];

