 const generated=Number.isSafeInteger(p.timestamp) && p.timestamp>=0 ? p.timestamp : null;
 if (generated !== null && state.climate_time != null && generated < state.climate_time) return null;
 const snapshot_id=generated === null ? null : 'climate:'+generated;
 const ac=section(p.stato_condizionatore), vmc=section(p.stato_vmc);
 const common={controller_generated_at_ms:generated,measurement_at_ms:null,snapshot_id,
