const COMPOSITE_TOPIC = "casa/clima/stato_completo";


// INIZIALIZZAZIONE CONTESTO
// v35: supporto al topic JSON composito clima/casa/stato_completo + humidex_reference separato.
if (!context.get("router_initialized_v106")) {
    context.set("router_initialized", false);
    context.set("router_initialized_v106", true);
}

if (!context.get("router_initialized")) {
    let mapCmdToLegacy = {};
    let mapLegacyToStat = {};

    registry.forEach(entity => {
        if (entity.int_cmd && entity.leg_cmd) {
            mapCmdToLegacy[entity.int_cmd] = {
                topic: entity.leg_cmd,
                broker: entity.broker,
                transform: entity.cmd_trans
            };
        }

        if (entity.int_stat && entity.leg_stat) {
            if (!mapLegacyToStat[entity.leg_stat]) {
                mapLegacyToStat[entity.leg_stat] = [];
            }

            // Evita solo duplicati identici leg_stat -> int_stat.
            const duplicate = mapLegacyToStat[entity.leg_stat]
                .some(route => route.topic === entity.int_stat);

            if (!duplicate) {
                mapLegacyToStat[entity.leg_stat].push({
                    topic: entity.int_stat,
                    transform: entity.stat_trans,
                    transform_func: entity.stat_trans_func
                });
            }
        }
    });

    context.set("mapCmdToLegacy", mapCmdToLegacy);
    context.set("mapLegacyToStat", mapLegacyToStat);
    context.set("lastSensorValues", {});
    context.set("router_initialized", true);
}

const mapCmdToLegacy = context.get("mapCmdToLegacy") || {};
const mapLegacyToStat = context.get("mapLegacyToStat") || {};
let lastSensorValues = context.get("lastSensorValues") || {};

let inTopic = msg.topic || "";
let inPayload = msg.payload;
let outMsgLegacy = null;
let outMsgsApp = [];
let outMsgBroadlink = null;

function getNestedValue(obj, path) {
    return path.split(".").reduce(
        (acc, part) => (acc !== undefined && acc !== null) ? acc[part] : undefined,
        obj
    );
}

function transformValue(config, value, lastVal) {
    if (config.transform_func) {
        return config.transform_func(value, lastVal);
    }

    if (config.transform && config.transform[value] !== undefined) {
        return config.transform[value];
    }

    if (
        typeof value !== "boolean" &&
        value !== "" &&
        !isNaN(parseFloat(value))
    ) {
        return parseFloat(value);
    }

    return value;
}

function emitState(config, value) {
    const lastVal = lastSensorValues[config.topic || config.int_stat];
    const outPayload = transformValue(config, value, lastVal);

    if (outPayload === undefined || outPayload === null) {
        return;
    }

    const topic = config.topic || config.int_stat;
    lastSensorValues[topic] = outPayload;

    outMsgsApp.push({
        topic: topic,
        payload: outPayload,
        qos: 1,
        retain: true
    });
}

const BROADLINK_INTERNAL_TOPICS = new Set([
    "zara/domotics/lights/shelflamp",
    "zara/domotics/lights/livinglamp",
    "zara/domotics/lights/tvlamp",
    "zara/domotics/lights/readinglight",
    "zara/domotics/lights/prolunga"
]);

// -----------------------------------------------------------------------------
// SCENE COMMAND BRIDGE
// -----------------------------------------------------------------------------
if (inTopic === "zara/interface/lights/scene/cmd") {
    return [null, null, null, msg];
}

// 1) UI / Digital Twin command -> Legacy command
if (inTopic.startsWith("zara/interface/")) {
    const route = mapCmdToLegacy[inTopic];

    if (route) {
        let outPayload = inPayload;

        if (route.transform && route.transform[inPayload] !== undefined) {
            outPayload = route.transform[inPayload];
        }

        const routedMsg = {
            topic: route.topic,
            payload: outPayload,
            broker: route.broker
        };

        // Le luci Broadlink verificate vengono inoltrate internamente
        // a function 17, evitando il publish MQTT intermedio.
        if (BROADLINK_INTERNAL_TOPICS.has(route.topic)) {
            outMsgBroadlink = routedMsg;
        } else {
            outMsgLegacy = routedMsg;
        }
    }
}

// 2) Topic JSON composito -> singoli state del Digital Twin
else if (inTopic === COMPOSITE_TOPIC) {
    let compositePayload = inPayload;

    // MQTT-in normalmente può essere configurato per fornire un object,
    // ma accettiamo anche una stringa JSON per rendere il router robusto.
    if (typeof compositePayload === "string") {
        try {
            compositePayload = JSON.parse(compositePayload);
        } catch (err) {
            node.warn("Digital Twin Router: JSON non valido su " + COMPOSITE_TOPIC);
            compositePayload = null;
        }
    }

    if (
        compositePayload &&
        typeof compositePayload === "object" &&
        !Array.isArray(compositePayload)
    ) {
        compositeRegistry.forEach(config => {
            const value = getNestedValue(compositePayload, config.json_path);

            if (value !== undefined && value !== null) {
                emitState(config, value);
            }
        });

        context.set("lastSensorValues", lastSensorValues);
    }
}

// 3) Topic legacy puntuale -> Digital Twin state
else {
    const routes = mapLegacyToStat[inTopic];

    if (routes && routes.length > 0) {
        routes.forEach(route => emitState(route, inPayload));
        context.set("lastSensorValues", lastSensorValues);
    }
}
return [
    outMsgLegacy,
    outMsgsApp.length > 0 ? outMsgsApp : null,
    outMsgBroadlink,
    null
];
